sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading) {
        return;
    }

    if (!newValue) {
        g_form.clearValue('minimum_cgpa');
        g_form.clearValue('max_backlogs');
        g_form.clearValue('eligible_branches');
        g_form.clearValue('skills');
        g_form.clearValue('mandatory_skills');
        g_form.clearValue('minimum_optional_skills');
        g_form.clearValue('job_role');
        g_form.clearValue('package');
        return;
    }

    g_form.getReference('company', function(company) {

        if (!company) {
            return;
        }

        // Eligibility Criteria
        g_form.setValue('minimum_cgpa', company.getValue('eligibility_cgpa'));
        g_form.setValue('max_backlogs', company.getValue('maximum_backlogs'));
        g_form.setValue('eligible_branches', company.getValue('allow_branches'));

        // Skills
        g_form.setValue('skills', company.getValue('skills'));
        g_form.setValue('mandatory_skills', company.getValue('mandatory_skills'));
        g_form.setValue(
            'minimum_optional_skills',
            company.getValue('minimum_optional_skills')
        );

        // Job Information
        g_form.setValue('job_role', company.getValue('job_role'));
        g_form.setValue('package', company.getValue('package'));
    });
}
